def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def as_pair(v, default=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return v[0], v[1]
        except Exception:
            pass
        return default

    def step_toward(src, dst):
        sx, sy = src
        dx, dy = dst
        return [clamp_step(dx - sx), clamp_step(dy - sy)]

    def dist1(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def safe_list(v):
        return v if isinstance(v, (list, tuple)) else []

    env = observation.get("environment_name", "resource_collection")
    sx, sy = as_pair(observation.get("self_position"), (0, 0))
    ox, oy = as_pair(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
