        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = corners[0]
        best_score = None
        for c in corners:
            score = dist1(c, opp_pos)
            if best_score is None or score > best_score:
                best_score = score
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = safe_list(observation.get("unclaimed_cells"))
        if not targets:
            targets = safe_list(observation.get("opponent_territory"))
        if not targets:
            targets = safe_list(observation.get("territory_targets"))
        if targets:
            best = None
            best_d = None
            for item in targets:
                p = as_pair(item, None)
                if p is None:
                    continue
                d = dist1(self_pos, p)
                if best_d is None or d < best_d:
                    best_d = d
                    best = p
            if best is not None:
                return step_toward(self_pos, best)
        return [clamp_step((gw - 1) - sx) if gw else 0, clamp_step((gh - 1) - sy) if gh else 0]

    resources = safe_list(observation.get("resources"))
    if resources:
        best = None
        best_d = None
        for item in resources:
            p = as_pair(item, None)
            if p is None:
