            d = dist1(self_pos, p)
            if best_d is None or d < best_d:
                best_d = d
                best = p
        if best is not None:
            return step_toward(self_pos, best)

    # Fallbacks: prefer moving away from opponent if close, otherwise toward center-ish / positive direction.
    if dist1(self_pos, opp_pos) <= 2:
        return step_toward(opp_pos, self_pos)

    cx = (gw - 1) // 2 if gw else sx
    cy = (gh - 1) // 2 if gh else sy
